  try {
    const response = await api.get(`/api-connections/${apiId}/replication-policy`);
    const policy = response.data?.data || {};
    setApiReplicationPolicy({
      enabled: policy.enabled !== false,
      cutoff_time: policy.cutoff_time || '',
